import {SHA256} from './sha256.js';
const $=id=>document.getElementById(id),MAX=256*1024*1024,CHUNK=1024*1024;
let key='',controller=null,active=false,blobURL=null,expected=null;
function checkAbort(){if(controller?.signal.aborted)throw new DOMException('Cancelled','AbortError');}
function status(s,p){$('status').textContent=s;if(p!==undefined)$('progress').value=p;}
function busy(on){active=on;for(const id of ['upload','refresh','lock','verify','file','verifyFile'])$(id).disabled=on;document.querySelectorAll('[data-download]').forEach(b=>b.disabled=on);$('cancel').hidden=!on;}
async function api(p,options={}){const res=await fetch('/api/'+p,{...options,headers:{Authorization:'Bearer '+key,...options.headers},signal:controller?.signal});if(!res.ok){let msg='Transfer failed';try{msg=(await res.json()).error||msg;}catch{}throw Error(msg);}return res;}
function clearSave(){if(blobURL)URL.revokeObjectURL(blobURL);blobURL=null;expected=null;$('save').hidden=true;$('verifyBox').hidden=true;$('verifyFile').value='';}
async function refresh(){const data=await(await api('files')).json();$('files').replaceChildren();if(!data.files.length){$('files').textContent='No shared files yet. Upload from either device, then refresh here.';return;}for(const f of data.files){const card=document.createElement('div');card.className='file';const name=document.createElement('div');name.className='name';name.textContent=f.name;const meta=document.createElement('div');meta.className='meta';meta.textContent=`${f.size.toLocaleString()} bytes · SHA-256 ${f.sha256}`;const b=document.createElement('button');b.textContent='Download & verify';b.dataset.download=f.id;b.disabled=active;b.onclick=()=>run(()=>download(f));card.append(name,meta,b);$('files').append(card);}}
async function run(fn){if(active)return;controller=new AbortController();busy(true);try{await fn();}catch(e){status(e.name==='AbortError'?'Cancelled. Refresh the shared list to check completed uploads.':e instanceof TypeError?'Connection lost. Check Wi-Fi and the Windows host, then retry from the start.':e.message);}finally{controller=null;busy(false);}}
$('connect').onsubmit=async e=>{e.preventDefault();try{const response=await fetch('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:$('key').value.replace(/\s/g,'')})});const result=await response.json();if(!response.ok)throw Error(result.error||'Unable to pair');key=result.token;await refresh();$('workspace').hidden=false;$('pair').hidden=true;$('key').value='';status('Connected. Select a file to send, or download from the shared list.',0);}catch(e){key='';status(e.message);}};
$('lock').onclick=()=>{fetch('/api/disconnect',{method:'POST',headers:{Authorization:'Bearer '+key}}).catch(()=>{});key='';clearSave();$('files').replaceChildren();$('workspace').hidden=true;$('pair').hidden=false;status('Disconnected. Stop the Windows server to revoke access on every device.',0);};
$('refresh').onclick=()=>run(async()=>{await refresh();status('Shared list refreshed.');});
$('cancel').onclick=()=>controller?.abort();
$('upload').onclick=()=>run(async()=>{
 const f=$('file').files[0];if(!f)throw Error('Choose a file first.');if(f.size>MAX)throw Error('This MVP supports files up to 256 MiB.');
 let id;clearSave();try{
  status('Preparing upload…',0);({id}=await(await api('uploads',{method:'POST',body:JSON.stringify({name:f.name,size:f.size})})).json());
  const hash=new SHA256();for(let offset=0;offset<f.size;offset+=CHUNK){checkAbort();const b=new Uint8Array(await f.slice(offset,offset+CHUNK).arrayBuffer());hash.update(b);await api(`uploads/${id}?offset=${offset}`,{method:'PUT',body:b});status(`Uploading ${f.name}: ${Math.min(offset+b.length,f.size).toLocaleString()} / ${f.size.toLocaleString()} bytes`,Math.min(100,(offset+b.length)/f.size*100));}
  status('Checking saved bytes on Windows…',100);const result=await(await api(`uploads/${id}/finish`,{method:'POST',body:JSON.stringify({sha256:hash.hex()})})).json();
  status(`Verified on Windows: ${result.name} · ${result.size.toLocaleString()} bytes. Refresh the other device to receive it.`,100);$('file').value='';await refresh();
 }catch(e){if(id)await fetch('/api/uploads/'+id,{method:'DELETE',headers:{Authorization:'Bearer '+key}}).catch(()=>{});throw e;}
});
async function download(f){clearSave();if(f.size>MAX)throw Error('File exceeds this browser MVP’s 256 MiB limit.');status(`Downloading ${f.name}…`,0);const res=await api('files/'+f.id),reader=res.body.getReader(),parts=[],hash=new SHA256();let size=0;try{for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>f.size||size>MAX)throw Error('Unexpected download size');hash.update(value);parts.push(value);status(`Receiving ${f.name}: ${size.toLocaleString()} / ${f.size.toLocaleString()} bytes`,f.size?size/f.size*100:100);}}catch(e){await reader.cancel().catch(()=>{});throw e;}
 if(size!==f.size||hash.hex()!==f.sha256)throw Error('Integrity check failed. Download discarded.');
 blobURL=URL.createObjectURL(new Blob(parts,{type:'application/octet-stream'}));expected=f;$('save').href=blobURL;$('save').download=f.name;$('save').hidden=false;$('verifyBox').hidden=false;status('Size and SHA-256 verified in browser. Tap Save verified file, then check the saved copy below.',100);
}
$('save').onclick=()=>status('Save requested. Your browser controls the destination. Select the saved copy below to verify it on disk.',100);
$('verify').onclick=()=>run(async()=>{const f=$('verifyFile').files[0];if(!expected||!f)throw Error('Choose the saved copy first.');if(f.size!==expected.size)throw Error('Saved copy has the wrong size.');const h=new SHA256();for(let o=0;o<f.size;o+=CHUNK){checkAbort();h.update(new Uint8Array(await f.slice(o,o+CHUNK).arrayBuffer()));status('Checking saved copy…',Math.min(100,(o+CHUNK)/f.size*100));await new Promise(r=>setTimeout(r,0));}if(h.hex()!==expected.sha256)throw Error('Saved copy SHA-256 does not match.');status('Saved copy verified: exact size and SHA-256 match.',100);});
